{
"title": "HTTP Status Class Share & Service Traffic",
"timeRange": { "from": "now-1h", "to": "now" },
"refreshIntervalMs": 15000,
"panels": [
{
"title": "Response Share by Status Class",
"description": "Shows the proportional share of HTTP responses grouped into 2xx, 3xx, 4xx and 5xx status classes, measured as the count of requests in each class.",
"viz": "pie",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT CASE WHEN status >= 200 AND status < 300 THEN '2xx' WHEN status >= 300 AND status < 400 THEN '3xx' WHEN status >= 400 AND status < 500 THEN '4xx' WHEN status >= 500 AND status < 600 THEN '5xx' ELSE 'other' END AS status_class, count(*) AS requests FROM http_requests GROUP BY status_class ORDER BY requests DESC"
},
"format": "number",
"options": { "legend": "right", "decimals": 0, "compact": true },
"layout": { "x": 0, "y": 0, "w": 6, "h": 4 }
,
"refreshIntervalMs": 15000
,
"timeRange": { "from": "now-1h", "to": "now" }
,
"id": "status-class-share"
}
,
{
"title": "Requests Handled per Service",
"description": "Compares how many requests each service handled, grouped by service name, as total request counts.",
"viz": "bar",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT service AS service, count(*) AS requests FROM http_requests GROUP BY service ORDER BY requests DESC"
},
"format": "number",
"options": { "legend": "none", "decimals": 0, "compact": true, "yAxis": { "label": "requests" } },
"layout": { "x": 6, "y": 0, "w": 6, "h": 4 }
,
"refreshIntervalMs": 15000
,
"timeRange": { "from": "now-1h", "to": "now" }
,
"id": "requests-per-service"
}
]
}
